class Solution {
    public int numberOfPaths(int n, int[][] corridors) {
        boolean[][] adj = new boolean[n + 1][n + 1];
        List<Integer>[] g = new List[n + 1];
        for (int i = 0; i <= n; i++) g[i] = new ArrayList<>();
        for (int[] c : corridors) {
            adj[c[0]][c[1]] = adj[c[1]][c[0]] = true;
            g[c[0]].add(c[1]);
            g[c[1]].add(c[0]);
        }
        int ans = 0;
        for (int u = 1; u <= n; u++)
            for (int v : g[u]) {
                if (v <= u) continue;
                for (int w : g[v])
                    if (w > v && adj[u][w]) ans++;
            }
        return ans;
    }
}
